// Íconos de la app (el ojito de R10) en PNG: favicon, iPhone y Android.
// /favicon.png, /apple-touch-icon.png, /icon-192.png, /icon-512.png e /icon-maskable.png llegan acá (ver vercel.json).
const I = {
  "32": "",
  "180": "",
  "192": "",
  "512": "",
  "m512": "",
};
export default function handler(req, res) {
  const n = String((req.query && req.query.n) || "192");
  res.setHeader("Content-Type", "image/png");
  res.setHeader("Cache-Control", "public, max-age=604800, s-maxage=604800");
  res.status(200).send(Buffer.from(I[n] || I["192"], "base64"));
}
